     let phys_addr: usize = phys_addr.into_raw_value();

     let pd_paddr: usize = KERNEL_PD_PADDR.load(Ordering::Acquire);
     // Check if the lazy mapper has been initialized.
     if pd_paddr == 0 {
         return Ok(());
