     let pde_idx: TableIndex = paging::pd_index(phys_addr);
     let pte_idx: TableIndex = paging::pt_index(phys_addr);

     // SAFETY: the PD is identity-mapped.
     let pd: Table<PageDirectoryEntry> = unsafe { Table::from_address(pd_paddr) };
